function Tile({ gid, arrow = true, stroke = 7 }) {
  return (
    <>
      <defs>
        <linearGradient id={gid} x1="0" y1="1" x2="1" y2="0">
          <stop offset="0" stopColor="#1E8BFF" />
          <stop offset="1" stopColor="#1FD1A5" />
        </linearGradient>
      </defs>
      <rect width="64" height="64" rx="15" fill={`url(#${gid})`} />
      <g transform="translate(32 32) scale(0.72) translate(-35 -31)">
        <path d={MARK} fill="none" stroke="#0A1A33" strokeWidth={stroke} strokeLinecap="round" />
        {arrow && <polygon points="59.5,10.5 58.8,18.2 51.8,11.2" fill="#0A1A33" />}
      </g>
    </>
  );
}

export function Mark({ size = 28 }) {
  const small = size < 40;
  return (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true">
      <Tile gid="qa-grad" arrow={!small} stroke={small ? 8 : 7} />
    </svg>
  );
}

export default function Logo({ height = 34 }) {
  return (
    <svg
      height={height}
      width={Math.round((height * 284) / 64)}
      viewBox="0 0 284 64"
      role="img"
      aria-label="QuotAlfa"
      className="block"
    >
      <Tile gid="qa-grad" />
      <path fill="#FFFFFF" d={WORD} />
      <path fill="#1FD1A5" d={WORD_A} />
    </svg>
  );
}
